WITH cleaned AS (SELECT *, DATE_FORMAT(event_time, 'MMM yyyy') AS event_time_label, CONCAT(event_type, '/', page) AS event_type_page FROM web_events WHERE duration_sec BETWEEN 386 AND 478), with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM cleaned), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN session_start_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_start_flag_tier, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list, MAX(event_time) AS ended_at, APPROX_PERCENTILE(burst_id, ARRAY(0.25, 0.5, 0.75)) AS burst_id_quartiles FROM sessionized GROUP BY CASE WHEN session_start_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY session_start_flag_tier
